    'act_plan' => ['Druh licencie', 'Licenc típusa', 'Licence type'],
    'plan_year' => ['1 rok', '1 év', '1 year'],
    'plan_year_badge' => ['Flexibilná', 'Rugalmas', 'Flexible'],
    'plan_year_per' => ['/ 12 mesiacov', '/ 12 hónap', '/ 12 months'],
    'plan_year_d' => ['Všetky funkcie a aktualizácie na rok. Ďalší nákup predĺži licenciu o rok.', 'Minden funkció és frissítés egy évig. Az újabb vásárlás egy évvel meghosszabbítja.', 'All features and updates for a year. Buying again extends it by a year.'],
    'plan_life' => ['Doživotná', 'Örökös', 'Lifetime'],
    'plan_life_badge' => ['Najvýhodnejšia', 'Legjobb ár', 'Best value'],
    'plan_life_per' => ['jednorazovo', 'egyszeri', 'one-time'],
    'plan_life_d' => ['Na jedno zariadenie (jednu MAC adresu) po celú dobu prevádzky služby.', 'Egy eszközre (egy MAC-címre) a szolgáltatás teljes működési idejére.', 'For one device (one MAC address) for as long as the service runs.'],
    'act_device_h' => ['Pre ktoré zariadenie?', 'Melyik eszközre?', 'For which device?'],
    'act_logged_device' => ['prihlásené zariadenie', 'bejelentkezett eszköz', 'logged-in device'],
    'act_key_why' => ['Kľúč overí, že licenciu kupuješ pre správne zariadenie – preklep v MAC by ju dal niekomu inému.', 'A kulcs igazolja, hogy a megfelelő eszközre veszed – egy elírt MAC-cím másnak adná a licencet.', 'The key confirms you’re buying for the right device – a typo in the MAC would give the licence to someone else.'],
    'act_email' => ['E-mail na doklad (nepovinné – Stripe sa spýta)', 'E-mail a bizonylathoz (nem kötelező – a Stripe megkérdezi)', 'E-mail for the receipt (optional – Stripe will ask)'],
    'act_consent' => ['Súhlasím s %s a žiadam o okamžitú aktiváciu. Beriem na vedomie, že tým strácam právo odstúpiť od zmluvy do 14 dní.', 'Elfogadom %s, és kérem az azonnali aktiválást. Tudomásul veszem, hogy ezzel elveszítem a 14 napos elállási jogot.', 'I agree to %s and request immediate activation. I understand that I thereby lose the 14-day right of withdrawal.'],
    'act_pay_btn' => ['Pokračovať na platbu', 'Tovább a fizetéshez', 'Continue to payment'],
    'pay_methods' => ['Karta · Apple Pay · Google Pay', 'Kártya · Apple Pay · Google Pay', 'Card · Apple Pay · Google Pay'],
    'act_pick_plan' => ['Vyber druh licencie.', 'Válaszd ki a licenc típusát.', 'Choose the licence type.'],
    'act_need_consent' => ['Bez súhlasu s podmienkami nemôžeme licenciu aktivovať.', 'A feltételek elfogadása nélkül nem aktiválhatjuk a licencet.', 'We can’t activate the licence without your consent to the terms.'],
    'act_already_life' => ['Toto zariadenie už má doživotnú licenciu – netreba nič kupovať.', 'Ennek az eszköznek már örökös licence van – nem kell semmit vásárolni.', 'This device already has a lifetime licence – nothing to buy.'],
    'act_q1' => ['Kedy sa licencia aktivuje?', 'Mikor aktiválódik a licenc?', 'When is the licence activated?'],
    'act_a1' => ['Hneď po zaplatení. Stačí reštartovať Arxon na zariadení.', 'Azonnal a fizetés után. Elég újraindítani az Arxont.', 'Right after payment. Just restart Arxon on the device.'],
    'act_q2' => ['Je v cene aj obsah?', 'Az ár tartalmat is tartalmaz?', 'Is any content included?'],
    'act_a2' => ['Nie. Licencia odomyká prehrávač, playlist si pridávaš vlastný.', 'Nem. A licenc a lejátszót oldja fel, a listát te adod hozzá.', 'No. The licence unlocks the player; you add your own playlist.'],
    'act_q3' => ['Kúpil som nový televízor.', 'Új tévét vettem.', 'I bought a new TV.'],
    'act_a3' => ['Licencia patrí jednému zariadeniu a na nové sa neprenáša. Nový televízor má vlastných 7 dní zadarmo.', 'A licenc egy eszközhöz tartozik, újra nem vihető át. Az új tévé saját 7 ingyenes napot kap.', 'A licence belongs to one device and can’t be moved. The new TV gets its own 7 free days.'],
    'act_q4' => ['Preinštaloval som aplikáciu.', 'Újratelepítettem az alkalmazást.', 'I reinstalled the app.'],
    'act_a4' => ['Licencia ostáva – na tom istom zariadení sa MAC adresa nemení.', 'A licenc megmarad – ugyanazon az eszközön a MAC-cím nem változik.', 'The licence stays – the MAC address doesn’t change on the same device.'],
    'act_q5' => ['Mám licenciu od predajcu.', 'Viszonteladótól van licencem.', 'I got a licence from a reseller.'],
    'act_a5' => ['Nemusíš nič platiť – predajca ju aktivuje na tvoju MAC adresu.', 'Nem kell fizetned – a viszonteladó aktiválja a MAC-címedre.', 'No need to pay – the reseller activates it on your MAC address.'],
    'prod_year' => ['ročná licencia', 'éves licenc', 'yearly licence'],
    'prod_lifetime' => ['doživotná licencia', 'örökös licenc', 'lifetime licence'],
    'prod_credits' => ['%d kreditov pre predajcu', '%d kredit viszonteladónak', '%d reseller credits'],
    'pay_disabled' => ['Platby ešte nie sú spustené. Licenciu ti zatiaľ aktivuje predajca alebo podpora.', 'A fizetés még nem indult el. A licencet addig a viszonteladó vagy az ügyfélszolgálat aktiválja.', 'Payments are not live yet. For now, a reseller or support will activate your licence.'],
    'pay_error' => ['Platobnú bránu sa nepodarilo otvoriť. Skús to o chvíľu.', 'Nem sikerült megnyitni a fizetési oldalt. Próbáld újra kicsit később.', 'Could not open the payment page. Please try again shortly.'],
    'pay_cancelled' => ['Platba bola zrušená – nič sa nestrhlo.', 'A fizetés megszakadt – nem történt terhelés.', 'Payment cancelled – nothing was charged.'],
    'pay_ok_license' => ['Ďakujeme! Licencia pre %s je aktívna. Reštartuj Arxon na zariadení.', 'Köszönjük! A(z) %s licence aktív. Indítsd újra az Arxont.', 'Thank you! The licence for %s is active. Restart Arxon on the device.'],
    'pay_ok_credits' => ['Ďakujeme! Kredity sú pripísané.', 'Köszönjük! A kreditek jóváírva.', 'Thank you! Credits have been added.'],
    'pay_manual' => ['Platba prijatá, ďakujeme. Licenciu alebo kredity ti dokončíme ručne – ozveme sa ti, prípadne napíš na podporu.', 'A fizetés beérkezett, köszönjük. A licencet vagy a krediteket kézzel véglegesítjük – jelentkezünk, vagy írj az ügyfélszolgálatnak.', 'Payment received, thank you. We’ll finish your licence or credits manually – we’ll be in touch, or contact support.'],
    'pay_pending' => ['Platba sa ešte spracúva. Licencia alebo kredity sa pripíšu automaticky hneď po potvrdení.', 'A fizetés feldolgozás alatt. A licenc vagy a kreditek a visszaigazolás után automatikusan jóváíródnak.', 'Payment is still processing. The licence or credits will be added automatically once confirmed.'],

    // --- návody ---
    'guides_h' => ['Návody', 'Útmutatók', 'Guides'],
    'guides_desc' => ['Inštalácia Arxonu, pridanie playlistu a aktivácia krok za krokom.', 'Az Arxon telepítése, lista hozzáadása és aktiválás lépésről lépésre.', 'Installing Arxon, adding a playlist and activation step by step.'],
    'guides_lead' => ['Vyber svoje zariadenie – inštalácia, pridanie playlistu a aktivácia krok za krokom.', 'Válaszd ki az eszközödet – telepítés, lista hozzáadása és aktiválás lépésről lépésre.', 'Choose your device – install, add a playlist and activate, step by step.'],
    'guides_platform' => ['Platforma', 'Platform', 'Platform'],
    'guides_req' => ['Požiadavky', 'Követelmények', 'Requirements'],
    'guides_trouble' => ['Nefunguje niečo? Pozri chybové hlásenia', 'Valami nem működik? Nézd meg a hibaüzeneteket', 'Something not working? See error messages'],
    'g1_t' => ['Nainštaluj Arxon', 'Telepítsd az Arxont', 'Install Arxon'],
    'g1_shot' => ['obchod s aplikáciami', 'alkalmazásbolt', 'app store'],
    'g2_t' => ['Zapíš si MAC a kľúč zariadenia', 'Jegyezd fel a MAC-címet és az eszközkulcsot', 'Note the MAC and device key'],
    'g2_d' => ['Po spustení ich Arxon ukáže na obrazovke. Neskôr ich nájdeš v Nastavenia → Údaje používateľa.', 'Indítás után az Arxon megmutatja őket. Később: Beállítások → Felhasználói adatok.', 'Arxon shows them after starting. Later in Settings → User info.'],
    'g2_shot' => ['obrazovka s MAC a kľúčom', 'MAC-cím és kulcs képernyő', 'MAC and key screen'],
    'g3_t' => ['Pridaj playlist', 'Add hozzá a listát', 'Add your playlist'],
    'g3_d' => ['Na arxonlabs.eu → Moje zariadenie zadaj MAC a kľúč a pridaj Xtream údaje alebo M3U odkaz. Zamkni ho PIN-om.', 'Az arxonlabs.eu → Eszközöm oldalon add meg a MAC-címet és a kulcsot, majd az Xtream adatokat vagy az M3U linket. Zárd PIN-nel.', 'On arxonlabs.eu → My device enter the MAC and key, then add Xtream details or an M3U link. Lock it with a PIN.'],
    'g3_shot' => ['formulár Pridať playlist', 'Lista hozzáadása űrlap', 'Add playlist form'],
    'g4_t' => ['Reštartuj a pozeraj', 'Indítsd újra és nézd', 'Restart and watch'],
    'g4_d' => ['Arxon si playlist načíta sám. Prvých 7 dní je zadarmo, potom aktivuj licenciu alebo ju získaj od predajcu.', 'Az Arxon magától betölti a listát. Az első 7 nap ingyenes, utána aktiváld a licencet vagy kérd a viszonteladótól.', 'Arxon loads the playlist by itself. The first 7 days are free, then activate a licence or get one from a reseller.'],
    'g4_shot' => ['zoznam kanálov', 'csatornalista', 'channel list'],
    'shot_placeholder' => ['[snímka obrazovky – %s]', '[képernyőkép – %s]', '[screenshot – %s]'],

