    'news_h' => ['Novinky', 'Újdonságok', 'What’s new'],
    'news_desc' => ['Čo je nové v Arxone.', 'Újdonságok az Arxonban.', 'What’s new in Arxon.'],
    'news_lead' => ['Čo je nové v Arxone. Aktualizácie sa na zariadenie stiahnu automaticky.', 'Újdonságok az Arxonban. A frissítések automatikusan letöltődnek.', 'What’s new in Arxon. Updates download to your device automatically.'],
    'news_filter' => ['Filter platformy', 'Platformszűrő', 'Platform filter'],
