    'news_empty' => ['Pre túto platformu zatiaľ nič.', 'Ehhez a platformhoz még nincs semmi.', 'Nothing for this platform yet.'],

    // --- podpora ---
    'sup_h' => ['Podpora', 'Támogatás', 'Support'],
    'sup_desc' => ['Chybové hlásenia, časté otázky a kontakt.', 'Hibaüzenetek, gyakori kérdések és kapcsolat.', 'Error messages, FAQ and contact.'],
    'sup_lead' => ['Väčšinu problémov vyriešiš za minútu. Arxon je len prehrávač – ak nejde konkrétny kanál, kontaktuj poskytovateľa playlistu.', 'A legtöbb problémát egy perc alatt megoldod. Az Arxon csak lejátszó – ha egy csatorna nem megy, keresd a lista szolgáltatóját.', 'Most problems take a minute to fix. Arxon is only a player – if a specific channel doesn’t work, contact your playlist provider.'],
    'sup_errors_h' => ['Chybové hlásenia', 'Hibaüzenetek', 'Error messages'],
    'err1_m' => ['Zariadenie sa nenašlo', 'Az eszköz nem található', 'Device not found'],
    'err1_d' => ['Skontroluj MAC adresu a kľúč – opíš ich presne z obrazovky Arxonu.', 'Ellenőrizd a MAC-címet és a kulcsot – másold pontosan az Arxon képernyőjéről.', 'Check the MAC address and key – copy them exactly from the Arxon screen.'],
    'err2_m' => ['Licencia neaktívna', 'A licenc inaktív', 'Licence inactive'],
    'err2_d' => ['Skúšobná doba skončila alebo licencia vypršala. Aktivuj ju na stránke Aktivácia alebo u predajcu.', 'A próbaidő vagy a licenc lejárt. Aktiváld az Aktiválás oldalon vagy a viszonteladónál.', 'The trial or licence has ended. Activate it on the Activation page or with your reseller.'],
    'err3_m' => ['Nesprávny PIN', 'Hibás PIN', 'Wrong PIN'],
    'err3_d' => ['Playlist je zamknutý PIN-om. Ak si ho zabudol, zmaž playlist a pridaj ho znova.', 'A lista PIN-nel zárolt. Ha elfelejtetted, töröld a listát és add hozzá újra.', 'The playlist is PIN locked. If you forgot it, delete the playlist and add it again.'],
    'err4_m' => ['Playlist sa nenačítal', 'A lista nem töltődött be', 'Playlist failed to load'],
    'err4_d' => ['Over Xtream údaje alebo M3U odkaz u poskytovateľa. Často ide o vypršané predplatné u neho.', 'Ellenőrizd az Xtream adatokat vagy az M3U linket a szolgáltatónál. Gyakran lejárt előfizetésről van szó.', 'Check the Xtream details or M3U link with your provider. Often their subscription has expired.'],
    'err5_m' => ['Skúšobná doba vypršala', 'A próbaidő lejárt', 'Trial expired'],
    'err5_d' => ['Prvých 7 dní je zadarmo. Pokračovať môžeš s ročnou alebo doživotnou licenciou.', 'Az első 7 nap ingyenes. Éves vagy örökös licenccel folytathatod.', 'The first 7 days are free. Continue with a yearly or lifetime licence.'],
    'sup_q1' => ['Kde nájdem MAC a kľúč zariadenia?', 'Hol találom a MAC-címet és az eszközkulcsot?', 'Where do I find the MAC and device key?'],
    'sup_a1' => ['Zobrazia sa pri prvom spustení. Neskôr v Arxone: Nastavenia → Údaje používateľa.', 'Az első indításkor jelennek meg. Később az Arxonban: Beállítások → Felhasználói adatok.', 'They appear on first start. Later in Arxon: Settings → User info.'],
    'sup_q2' => ['Ako pridám playlist?', 'Hogyan adok hozzá listát?', 'How do I add a playlist?'],
    'sup_a2' => ['Na stránke Moje zariadenie sa prihlás MAC adresou a kľúčom a pridaj Xtream údaje alebo M3U odkaz. Potom Arxon reštartuj.', 'Az Eszközöm oldalon jelentkezz be MAC-címmel és kulccsal, add meg az Xtream adatokat vagy az M3U linket, majd indítsd újra az Arxont.', 'On My device, log in with the MAC and key, add Xtream details or an M3U link, then restart Arxon.'],
    'sup_q3' => ['Predávate kanály alebo playlisty?', 'Árultok csatornákat vagy listákat?', 'Do you sell channels or playlists?'],
    'sup_a3' => ['Nie. Arxon je len prehrávač, obsah si zabezpečuješ sám od svojho poskytovateľa.', 'Nem. Az Arxon csak lejátszó, a tartalmat a saját szolgáltatódtól szerzed be.', 'No. Arxon is only a player; you get content from your own provider.'],
    'sup_q4' => ['Môžem licenciu preniesť na iný televízor?', 'Átvihetem a licencet másik tévére?', 'Can I move my licence to another TV?'],
    'sup_a4' => ['Nie. Platí 1 zariadenie = 1 MAC adresa = 1 licencia. Ak aplikáciu preinštaluješ na tom istom zariadení, MAC sa nemení a licencia ostáva.', 'Nem. 1 eszköz = 1 MAC-cím = 1 licenc. Ha ugyanazon az eszközön újratelepíted, a MAC nem változik, a licenc megmarad.', 'No. 1 device = 1 MAC address = 1 licence. If you reinstall on the same device, the MAC stays and so does the licence.'],
    'sup_q5' => ['Kanál sa seká alebo nenačíta.', 'A csatorna akadozik vagy nem tölt be.', 'A channel stutters or won’t load.'],
    'sup_a5' => ['Skús iný kanál. Ak nejde žiadny, reštartuj router a zariadenie. Ak nejde len jeden, problém je u poskytovateľa playlistu.', 'Próbálj másik csatornát. Ha egyik sem megy, indítsd újra a routert és az eszközt. Ha csak egy nem megy, a hiba a szolgáltatónál van.', 'Try another channel. If none work, restart your router and device. If only one fails, the issue is with the playlist provider.'],
    'sup_q6' => ['Ako zmením jazyk aplikácie?', 'Hogyan változtatom meg az alkalmazás nyelvét?', 'How do I change the app language?'],
    'sup_a6' => ['Nastavenia → Jazyk menu. Jazyk zvuku a titulkov vyberieš počas prehrávania dlhým stlačením OK.', 'Beállítások → Menü nyelve. A hang és felirat nyelvét lejátszás közben az OK hosszú lenyomásával választod.', 'Settings → Menu language. Audio and subtitle language: long-press OK during playback.'],
    'sup_q7' => ['Preinštaloval som Arxon a nemám playlisty.', 'Újratelepítettem az Arxont, és eltűntek a listák.', 'I reinstalled Arxon and my playlists are gone.'],
    'sup_a7' => ['Ak si mal zapnutú cloudovú zálohu, obnov ju v Nastavenia → Cloudová záloha (telefón, názov zariadenia, PIN). Inak playlist pridaj znova na stránke Moje zariadenie.', 'Ha a felhőmentés be volt kapcsolva, állítsd vissza: Beállítások → Felhőmentés (telefon, eszköznév, PIN). Különben add hozzá újra a listát az Eszközöm oldalon.', 'If cloud backup was on, restore it in Settings → Cloud backup (phone, device name, PIN). Otherwise add the playlist again on My device.'],
    'sup_form_h' => ['Napíš nám', 'Írj nekünk', 'Write to us'],
    'sup_mac_opt' => ['MAC adresa (nepovinné)', 'MAC-cím (nem kötelező)', 'MAC address (optional)'],
    'sup_msg' => ['Správa', 'Üzenet', 'Message'],
    'sup_msg_ph' => ['Zariadenie, verzia Arxonu a čo sa deje', 'Eszköz, Arxon-verzió és mi történik', 'Device, Arxon version and what happens'],
    'sup_msg_len' => ['Správa musí mať 10 až 4000 znakov.', 'Az üzenet 10–4000 karakter legyen.', 'The message must be 10 to 4000 characters.'],
    'sup_no_pass' => ['Nikdy nepíš heslá ani kľúč zariadenia.', 'Soha ne írj jelszót vagy eszközkulcsot.', 'Never send passwords or your device key.'],
    'sup_no_mail' => ['Formulár zatiaľ nie je nastavený. Napíš nám priamo e-mailom.', 'Az űrlap még nincs beállítva. Írj nekünk közvetlenül e-mailben.', 'The form isn’t set up yet. Please e-mail us directly.'],
    'sup_send_fail' => ['Správu sa nepodarilo odoslať. Napíš nám priamo na %s.', 'Az üzenetet nem sikerült elküldeni. Írj közvetlenül: %s.', 'The message could not be sent. Please write to %s.'],
    'sup_sent' => ['Ďakujeme, správa odišla. Odpovieme na tvoj e-mail.', 'Köszönjük, az üzenet elment. Az e-mail-címedre válaszolunk.', 'Thanks, your message was sent. We’ll reply by e-mail.'],
    'sup_reply_time' => ['Odpovedáme zvyčajne do 24 hodín v pracovné dni.', 'Általában munkanapokon 24 órán belül válaszolunk.', 'We usually reply within 24 hours on working days.'],

